class Solution {
public:
    vector<int> advantageCount(vector<int>& nums1, vector<int>& nums2) {
        int n = nums1.size();
        sort(nums1.begin(), nums1.end());

        vector<pair<int,int>> v2;
        for (int i = 0; i < n; i++) {
            v2.push_back({nums2[i], i});
        }
        sort(v2.begin(), v2.end());

        vector<int> result(n);
        int lo = 0, hi = n - 1;
        for (int i = n - 1; i >= 0; i--) {
            if (nums1[hi] > v2[i].first) {
                result[v2[i].second] = nums1[hi];
                hi--;
            } else {
                result[v2[i].second] = nums1[lo];
                lo++;
            }
        }
        return result;
    }
};
